from lib import *
R = J('z14'); c, rc, ex = R['create'], R['reconnect'], R['expired']
def S(k): return [l for l in out('z14').split('== ')[k].splitlines()[1:] if l.strip()]
steps = [
    step(f"同时建立 300 个会话:用时 {c['ms']:.0f} ms(约 {300000 / c['ms']:.0f} 个/秒);zxid 增加了 {c['dz']}——每个新会话都是一个写事务(createSession),写进事务日志。会话建立不是「免费」的,风暴时它们都要排队写日志。", t=tl(S(1)), kv=KV([['每个新会话', '一个写事务(zxid +1)']], ['每个新会话'])),
    step(f"服务端重启(数据保留),300 个客户端同时重连:服务端 {rc['ready']:.0f} ms 后能响应;第一个客户端 {rc['first']:.0f} ms 重连、中位 {rc['med']:.0f} ms、最后一个 {rc['last'] / 1000:.1f} s——{rc['n']}/300 全部回来,会话 id 集合不变。尾部延迟(最慢的一个比中位慢 10 倍)来自客户端自己的重连退避,不是服务端处理不过来(这一点是我推测的,没有逐个确认)。", t=tl(S(2)), b=bars([['服务端就绪', rc['ready'], f"{rc['ready']:.0f} ms"], ['第一个重连', rc['first'], f"{rc['first']:.0f} ms"], ['中位', rc['med'], f"{rc['med']:.0f} ms"], ['最后一个', rc['last'], f"{rc['last']:.0f} ms"]], rc['last'] * 1.05, mark=[3], done=[0, 1, 2]), kv=KV([['重连尾部', '最慢的约 11 s']], ['重连尾部'])),
    step(f"客户端会话超时设成最小值 4 秒、服务端停 6 秒再起:重启 8 秒后 {ex['back']}/300 个已连上,状态出现过 LOST 的 {ex['lost']} 个,换了新会话 id 的 {ex['newsids']} 个,zxid 增加 {ex['dz']}(新会话 + 过期会话的关闭事务)。会话并没有全部过期——服务端重启后重新计时,给了客户端一段缓冲;但已经有一批客户端丢了会话,它们的临时节点会同时消失。", t=tl(S(3)), mark=[0], kv=KV([['部分会话过期', f"{ex['lost']} / 300"], ['zxid', f"+{ex['dz']}"]], ['部分会话过期'])),
]
A = dict(
    n=14, series='zookeeper', tags='ZooKeeper,会话风暴,重连,真实验证,动画演示',
    desc=f'会话风暴实测(300 个客户端):建立 300 个会话 {c["ms"]:.0f} ms、zxid +{c["dz"]}(每个会话一个事务);服务端重启后 300 个客户端全部重连,最慢 {rc["last"] / 1000:.1f} s;会话超时 4 s 而服务端停 6 s 时有 {ex["lost"]} 个会话过期。',
    lead='成百上千个客户端同时断开又同时重连,就是「会话风暴」。这篇用 300 个 kazoo 客户端,量建立会话的代价、服务端重启后全部重连的时间分布,以及会话超时较短时有多少会话被判定过期。',
    facts=[(f'zxid +{c["dz"]}', '300 个新会话 = 300 个 createSession 写事务'), (f'{rc["med"]:.0f} ms / {rc["last"] / 1000:.1f} s', '服务端重启后客户端重连时间的中位数 / 最慢'), (f'{ex["lost"]} / 300', '会话超时 4 s、服务端停 6 s 后状态出现过 LOST 的客户端数')],
    body=[
        sec('建立会话的代价', '', term('', blk('z14', 1))),
        sec('服务端重启后的重连', '', term('', blk('z14', 2)), '<p>300 个客户端对一个单机 ZooKeeper 来说负载并不大;如果是几千个客户端,客户端自己的重连退避与服务端的连接限流(第 19、26 篇)会变得更重要,本文没有测到那个规模。</p>'),
        sec('会话超时较短时', '', term('', blk('z14', 3)), '<p>数字每次运行都会不同(取决于恢复时机)。它说明的是:会话超时设得太短,一次几秒的重启就可能让一批会话过期,临时节点(比如服务注册)集中消失,引发二次风暴。</p>'),
        sec('分步演示', '', demo('会话风暴', [('t', 'term', '输出'), ('b', 'bars', '时间'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_Z + '。单机,JVM 堆 256 MiB,maxClientCnxns=1000;300 个 kazoo 客户端(同一进程内的线程);各场景只测一次', '没有验证:几千个以上的客户端、Java 客户端的重连退避、集群里 leader 重启的风暴、服务端连接限流(connection throttling)的效果、重连时间尾部的真正原因'],
)
